// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/**
 * @title  SCDO Test USD (tUSDT) -- TEST SETTLEMENT TOKEN, NO VALUE
 * @notice Demonstration token for an internal OTC / exchange settlement proof of concept
 *         operated by 9Y9 PTY LTD on SCDO shard0 (chainId 5680).
 *         THIS IS A TEST TOKEN. IT HAS NO MONETARY VALUE, IS NOT REDEEMABLE FOR USD, USDT
 *         OR ANYTHING ELSE, IS NOT ISSUED OR OFFERED TO THE PUBLIC, IS NOT AFFILIATED WITH
 *         TETHER, AND IS NOT A STABLECOIN, DEPOSIT, STORED-VALUE FACILITY OR FINANCIAL PRODUCT.
 * @dev    Self-contained ERC-20 (no external imports) with:
 *         - owner-only mint     (models an OTC-desk deposit being recorded)
 *         - owner-only burnFrom (models an OTC redemption); holders may burn their own balance
 *         - pausable transfers/mint/burn (circuit breaker)
 *         - owner-managed blocklist (freeze/unfreeze) as an AML control demo: a frozen address
 *           cannot send, receive, approve, spend allowances, be minted to, or self-burn.
 *           The owner can still burnFrom a frozen address (e.g. court-ordered destruction).
 *         - two-step ownership transfer
 *         Decimals = 6 (matches USDT on major chains, so amounts map 1:1 to USDT micro-units).
 */
contract SCDOTestUSD {
    // ------------------------------------------------------------------ metadata
    string public constant name = "SCDO Test USD (TEST ONLY - NO VALUE)";
    string public constant symbol = "tUSDT";
    uint8 public constant decimals = 6;
    string public constant disclaimer =
        "TEST TOKEN ONLY. No monetary value. Not redeemable. Not issued or offered to the public. "
        "Not affiliated with Tether. Internal OTC-settlement demo by 9Y9 PTY LTD on SCDO shard0 (chainId 5680).";

    // ------------------------------------------------------------------ state
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => bool) public isFrozen;

    address public owner;
    address public pendingOwner;
    bool public paused;

    // ------------------------------------------------------------------ events
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Mint(address indexed to, uint256 value, bytes32 indexed ref);
    event Burn(address indexed from, uint256 value, bytes32 indexed ref);
    event Frozen(address indexed account, bytes32 indexed ref);
    event Unfrozen(address indexed account, bytes32 indexed ref);
    event Paused(address indexed account);
    event Unpaused(address indexed account);
    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    // ------------------------------------------------------------------ errors
    error NotOwner();
    error NotPendingOwner();
    error EnforcedPause();
    error ExpectedPause();
    error ZeroAddress();
    error AccountFrozen(address account);
    error InsufficientBalance(uint256 available, uint256 required);
    error InsufficientAllowance(uint256 available, uint256 required);

    // ------------------------------------------------------------------ modifiers
    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier whenNotPaused() {
        if (paused) revert EnforcedPause();
        _;
    }

    modifier notFrozen(address account) {
        if (isFrozen[account]) revert AccountFrozen(account);
        _;
    }

    constructor() {
        owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    // ------------------------------------------------------------------ ERC-20
    function transfer(address to, uint256 value)
        external whenNotPaused notFrozen(msg.sender) notFrozen(to) returns (bool)
    {
        _transfer(msg.sender, to, value);
        return true;
    }

    function approve(address spender, uint256 value)
        external notFrozen(msg.sender) notFrozen(spender) returns (bool)
    {
        if (spender == address(0)) revert ZeroAddress();
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value)
        external whenNotPaused notFrozen(msg.sender) notFrozen(from) notFrozen(to) returns (bool)
    {
        uint256 current = allowance[from][msg.sender];
        if (current != type(uint256).max) {
            if (current < value) revert InsufficientAllowance(current, value);
            unchecked {
                allowance[from][msg.sender] = current - value;
            }
        }
        _transfer(from, to, value);
        return true;
    }

    // ------------------------------------------------------------------ issuer ops
    /// @notice Record a (test) OTC-desk deposit by minting tUSDT. `ref` = off-chain deposit reference.
    function mint(address to, uint256 value, bytes32 ref) external onlyOwner whenNotPaused notFrozen(to) {
        if (to == address(0)) revert ZeroAddress();
        totalSupply += value;
        unchecked {
            balanceOf[to] += value; // cannot overflow: bounded by totalSupply
        }
        emit Transfer(address(0), to, value);
        emit Mint(to, value, ref);
    }

    /// @notice Settle a (test) OTC redemption by burning tUSDT held by `from`.
    function burnFrom(address from, uint256 value, bytes32 ref) external onlyOwner whenNotPaused {
        _burn(from, value, ref);
    }

    /// @notice Holder burns its own tokens (e.g. customer handing back tokens for redemption).
    function burn(uint256 value, bytes32 ref) external whenNotPaused notFrozen(msg.sender) {
        _burn(msg.sender, value, ref);
    }

    // ------------------------------------------------------------------ compliance (AML demo)
    /// @notice Freeze an address (blocklist). `ref` = off-chain case / alert reference.
    function freeze(address account, bytes32 ref) external onlyOwner {
        if (account == address(0)) revert ZeroAddress();
        isFrozen[account] = true;
        emit Frozen(account, ref);
    }

    function unfreeze(address account, bytes32 ref) external onlyOwner {
        isFrozen[account] = false;
        emit Unfrozen(account, ref);
    }

    function pause() external onlyOwner {
        if (paused) revert EnforcedPause();
        paused = true;
        emit Paused(msg.sender);
    }

    function unpause() external onlyOwner {
        if (!paused) revert ExpectedPause();
        paused = false;
        emit Unpaused(msg.sender);
    }

    // ------------------------------------------------------------------ ownership (2-step)
    function transferOwnership(address newOwner) external onlyOwner {
        pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner, newOwner);
    }

    function acceptOwnership() external {
        if (msg.sender != pendingOwner) revert NotPendingOwner();
        emit OwnershipTransferred(owner, msg.sender);
        owner = msg.sender;
        pendingOwner = address(0);
    }

    // ------------------------------------------------------------------ internals
    function _transfer(address from, address to, uint256 value) internal {
        if (to == address(0)) revert ZeroAddress();
        uint256 bal = balanceOf[from];
        if (bal < value) revert InsufficientBalance(bal, value);
        unchecked {
            balanceOf[from] = bal - value;
            balanceOf[to] += value; // cannot overflow: bounded by totalSupply
        }
        emit Transfer(from, to, value);
    }

    function _burn(address from, uint256 value, bytes32 ref) internal {
        uint256 bal = balanceOf[from];
        if (bal < value) revert InsufficientBalance(bal, value);
        unchecked {
            balanceOf[from] = bal - value;
            totalSupply -= value; // cannot underflow: value <= bal <= totalSupply
        }
        emit Transfer(from, address(0), value);
        emit Burn(from, value, ref);
    }
}
